// Convierte el error que publica la app en un aviso legible.
// Tema: labelbridge/<canal>/errors
// Mensaje: {"id","status","error","agent","printer","at"}
const topic = String($json.topic ?? '');
const canal = topic.split('/')[1] || 'desconocido';

let m = $json.message;
if (typeof m === 'string') {
  try {
    m = JSON.parse(m);
  } catch (e) {
    m = { error: m };
  }
}
m = m || {};

const asunto = `LabelBridge: fallo de impresión en "${canal}"${m.id ? ` (${m.id})` : ''}`;
const texto = [
  `Canal: ${canal}`,
  `Trabajo: ${m.id ?? '-'}`,
  `Estado: ${m.status ?? 'failed'}`,
  `Error: ${m.error ?? '-'}`,
  `Impresora: ${m.printer ?? '-'}`,
  `Equipo: ${m.agent ?? '-'}`,
  `Fecha: ${m.at ?? new Date().toISOString()}`,
].join('\n');

return { json: { canal, asunto, texto, detalle: m } };
